func (this *Bitstamp) ParseWsTrade(trade any, optionalArgs ...any) any {
	//
	//     {
	//         "buy_order_id": 1211625836466176,
	//         "amount_str": "1.08000000",
	//         "timestamp": "1584642064",
	//         "microtimestamp": "1584642064685000",
	//         "id": 108637852,
	//         "amount": 1.08,
	//         "sell_order_id": 1211625840754689,
	//         "price_str": "6294.77",
	//         "type": 1,
	//         "price": 6294.77
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var microtimestamp *int64 = this.SafeInteger(trade, "microtimestamp", 0)
	var id *string = this.SafeString(trade, "id")
	var timestamp int64 = this.ParseToInt(ccxt.Divide(microtimestamp, 1000))
	var price *string = this.SafeString(trade, "price")
	var amount *string = this.SafeString(trade, "amount")
	var marketResolved any = func() any {
		if market == nil {
			return this.SafeMarket(nil, market)
		}
		return market
	}()
	var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(marketResolved, "symbol"))
	var sideRaw *int64 = this.SafeInteger(trade, "type")
	var side string = "sell"
	if sideRaw != nil && *sideRaw == 0 {
		side = "buy"
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"id":           id,
		"order":        nil,
		"type":         nil,
		"takerOrMaker": nil,
		"side":         side,
		"price":        price,
		"amount":       amount,
		"cost":         nil,
		"fee":          nil,
	}, marketResolved)
}
func (this *Bitstamp) HandleTrade(client any, message map[string]any) {
	//
	//     {
	//         "data": {
	//             "buy_order_id": 1207733769326592,
	//             "amount_str": "0.14406384",
	//             "timestamp": "1583691851",
	//             "microtimestamp": "1583691851934000",
	//             "id": 106833903,
	//             "amount": 0.14406384,
	//             "sell_order_id": 1207733765476352,
	//             "price_str": "8302.92",
	//             "type": 0,
	//             "price": 8302.92
	//         },
	//         "event": "trade",
	//         "channel": "live_trades_btcusd"
	//     }
	//
	// the trade streams push raw trade information in real-time
	// each trade has a unique buyer and seller
	var channel *string = this.SafeString(message, "channel")
	if channel == nil {
		return
	}
	var parts []string = strings.Split(*channel, "_")
	var marketId *string = this.SafeString(parts, 2)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "trades:" + *symbol
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var trade map[string]any = ccxt.MapTyped(this.ParseWsTrade(data, market))
	var tradesArray any = this.SafeValue(this.Trades, symbol)
	if ccxt.IsEqual(tradesArray, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		tradesArray = ccxt.NewArrayCache(limit)
		ccxt.AddElementToObject(this.Trades, symbol, tradesArray)
	}
	tradesArray.(ccxt.Appender).Append(trade)
	client.(ccxt.ClientInterface).Resolve(tradesArray, messageHash)
}

